using Finance.Core;
using System.Data;
using System.Text;
using System.IO.Compression;

static class Tests
{
    static int passed,failed;
    static readonly List<string> Created=[];
    static int Day(int y=2026,int m=10,int d=1)=>new DateOnly(y,m,d).DayNumber;
    static long M(decimal v)=>Value.Money(v);
    static void Eq<T>(T expected,T actual,string label=""){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"{label}: expected {expected}, got {actual}");}
    static void Fail(Action a){try{a();}catch(BusinessException){return;}throw new Exception("Expected validation to reject the operation.");}
    static void Test(string title,Action action){try{action();passed++;Console.WriteLine("PASS | "+title);}catch(Exception ex){failed++;Console.WriteLine("FAIL | "+title+" | "+ex);}}
    sealed class Fixture
    {
        public Engine E;public string Dir;public long Customer,Supplier,Bank,Bank2,Emp,Site,Cat;
        public Fixture(decimal salary=30000){Dir=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"fms-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Dir);Created.Add(Dir);E=new(System.IO.Path.Combine(Dir,"business.db"));E.Setup("tester","TestPassword123!");E.SaveMaster("Company",new(){["Name"]="Test Company",["StateCode"]="21"},1);
            Customer=E.SaveMaster("Party",new(){["Kind"]="Customer",["Code"]="C1",["Name"]="Customer 1",["StateCode"]="21"});Supplier=E.SaveMaster("Party",new(){["Kind"]="Supplier",["Code"]="S1",["Name"]="Supplier 1",["StateCode"]="21"});Bank=E.SaveMaster("Bank",new(){["Name"]="Bank 1",["AccountNumber"]="001"});Bank2=E.SaveMaster("Bank",new(){["Name"]="Bank 2",["AccountNumber"]="002"});Emp=E.SaveMaster("Employee",new(){["Code"]="E1",["Name"]="Employee 1",["JoinDay"]=Day(2025,1,1),["Salary"]=M(salary),["EPF"]=1,["ESIC"]=1});Site=E.SaveMaster("Site",new(){["Code"]="SITE1",["Name"]="Site 1"});Cat=E.SaveMaster("Category",new(){["Name"]="Test Expense"});E.Opening(Day(2026,4,1),[new("BANK",M(1000000),Bank:Bank)],"Opening trial balance");}
        public long Invoice(string kind="Sales",string number="INV-1",decimal amount=1000,string pos="21",bool post=true,bool itc=true)=>E.SaveInvoice(new(kind,number,kind=="Sales"?Customer:Supplier,Day(),Day(2026,10,31),pos,"PO","",[new("Material","7214",1,"Nos",M(amount),0,18)],ITC:itc),post);
        public long Receipt(long inv,decimal amount)=>E.Move(new("Customer Receipt",Day(2026,10,5),M(amount),Bank,Party:Customer,Allocations:[new(inv,M(amount))]),true);
        public long Advance(decimal amount=10000,bool staff=false)=>E.Move(new(staff?"Staff Advance":"Employee Advance",Day(),M(amount),Bank,Employee:Emp,Site:staff?Site:null),false);
        public long Loan(decimal amount=10000)=>E.CreateInstrument(new("Employee Loan","EL-1",Day(),M(amount),Bank,Emp,EMI:M(1000),RecoveryDay:Day(),Installments:10));
        public long FD(string no="FD-1",decimal amount=10000)=>E.CreateInstrument(new("FD",no,Day(),M(amount),Bank,MaturityDay:Day(2027,10,1),Rate:7));
        public long BG()=>E.SaveBG(new("BG-1",Day(),Bank,"Branch","Beneficiary",M(100000),"Performance","PO",Day(2027,1,1),Day(2027,2,1)));
        public long Voucher(long invoice){using var d=E.Open();return d.N("SELECT VoucherId FROM Invoice WHERE Id=@p0",invoice);}
    }
    static void Main()
    {
        Test("Decimal paise rounding",()=>{Eq(101L,M(1.005m));Eq(-101L,M(-1.005m));Eq("06-10-2026",Value.Date(Day(2026,10,6)));Eq("2025-26",Value.FY(Day(2026,3,31)));Eq("2026-27",Value.FY(Day(2026,4,1)));});
        Test("Setup, hashed password, login and password change",()=>{var f=new Fixture();using var d=f.E.Open();var r=d.Row("SELECT * FROM AppUser");Eq(32,((byte[])r["Hash"]).Length);Fail(()=>f.E.Login("tester","wrong"));f.E.ChangePassword("TestPassword123!","ChangedPassword123!");f.E.Logout();Fail(()=>f.E.Balance("BANK"));f.E.Login("tester","ChangedPassword123!");Eq(M(1000000),f.E.Balance("BANK"));});
        Test("Intra-state sale posts once and has no bank movement",()=>{var f=new Fixture();long id=f.Invoice();Eq(M(1180),f.E.Balance("AR"));Eq(-M(90),f.E.Balance("OCGST"));Eq(-M(90),f.E.Balance("OSGST"));Eq(0L,f.E.Balance("OIGST"));Eq(M(1000000),f.E.Balance("BANK"));Eq(M(1180),f.E.Outstanding(id));Fail(()=>f.E.PostInvoice(id));Eq(M(1180),f.E.Balance("AR"));});
        Test("Inter-state sale and place of supply",()=>{var f=new Fixture();f.Invoice(pos:"19");Eq(-M(180),f.E.Balance("OIGST"));Eq(0L,f.E.Balance("OCGST"));});
        Test("Draft has no posting then posts atomically",()=>{var f=new Fixture();var id=f.Invoice(post:false);Eq(0L,f.E.Balance("AR"));f.E.PostInvoice(id);Eq(M(1180),f.E.Balance("AR"));});
        Test("Duplicate sale rejected and rolled back",()=>{var f=new Fixture();f.Invoice();Fail(()=>f.Invoice());using var d=f.E.Open();Eq(1L,d.N("SELECT COUNT(*) FROM Invoice"));Eq(M(1180),f.E.Balance("AR"));});
        Test("Supplier plus invoice duplicate key",()=>{var f=new Fixture();f.Invoice("Purchase");Fail(()=>f.Invoice("Purchase"));long other=f.E.SaveMaster("Party",new(){["Kind"]="Supplier",["Code"]="S2",["Name"]="Supplier 2",["StateCode"]="21"});f.E.SaveInvoice(new("Purchase","INV-1",other,Day(),Day(),"21","","",[new("Work","9987",1,"",M(1000),0)]));Eq(-M(2360),f.E.Balance("AP"));});
        Test("Purchase GST and non-ITC capitalization",()=>{var f=new Fixture();f.Invoice("Purchase");Eq(M(90),f.E.Balance("ICGST"));Eq(-M(1180),f.E.Balance("AP"));f.Invoice("Purchase","P2",itc:false);Eq(M(2180),f.E.Balance("PURCHASE"));Eq(M(90),f.E.Balance("ICGST"));});
        Test("Manual rate requires explicit verification",()=>{var f=new Fixture();var x=new InvoiceInput("Sales","X",f.Customer,Day(),Day(),"21","","",[new("Item","",1,"",M(100),0,7)]);Fail(()=>f.E.SaveInvoice(x));f.E.SaveInvoice(x with{ManualRateVerified=true});Eq(M(107),f.E.Balance("AR"));});
        Test("Discount cannot exceed gross and no orphan records",()=>{var f=new Fixture();Fail(()=>f.E.SaveInvoice(new("Sales","X",f.Customer,Day(),Day(),"21","","",[new("Item","",1,"",M(100),M(200))])));using var d=f.E.Open();Eq(0L,d.N("SELECT COUNT(*) FROM Invoice"));});
        Test("Partial receipt updates all balances once",()=>{var f=new Fixture();long id=f.Invoice();f.Receipt(id,500);Eq(M(680),f.E.Outstanding(id));Eq(M(680),f.E.Balance("AR"));Eq(M(1000500),f.E.Balance("BANK"));f.Receipt(id,680);Eq(0L,f.E.Outstanding(id));});
        Test("Multiple invoices in one receipt",()=>{var f=new Fixture();long a=f.Invoice(),b=f.Invoice(number:"INV-2");f.E.Move(new("Customer Receipt",Day(2026,10,5),M(1500),f.Bank,Party:f.Customer,Allocations:[new(a,M(1180)),new(b,M(320))]),true);Eq(0L,f.E.Outstanding(a));Eq(M(860),f.E.Outstanding(b));});
        Test("Over-allocation rejected, bank unchanged",()=>{var f=new Fixture();long id=f.Invoice();Fail(()=>f.Receipt(id,2000));Eq(M(1000000),f.E.Balance("BANK"));Eq(M(1180),f.E.Outstanding(id));});
        Test("Receipt belonging to wrong customer rejected",()=>{var f=new Fixture();long id=f.Invoice();long other=f.E.SaveMaster("Party",new(){["Kind"]="Customer",["Code"]="C2",["Name"]="Other",["StateCode"]="21"});Fail(()=>f.E.Move(new("Customer Receipt",Day(),M(1180),f.Bank,Party:other,Allocations:[new(id,M(1180))]),true));});
        Test("Supplier part payment and allocation",()=>{var f=new Fixture();long id=f.Invoice("Purchase");f.E.Move(new("Supplier Payment",Day(),M(180),f.Bank,Party:f.Supplier,Allocations:[new(id,M(180))]),false);Eq(-M(1000),f.E.Balance("AP"));Eq(M(1000),f.E.Outstanding(id));Eq(M(999820),f.E.Balance("BANK"));});
        Test("Bank transfer is not income or expense",()=>{var f=new Fixture();f.E.Transfer(Day(),f.Bank,f.Bank2,M(200000),"Transfer");Eq(M(800000),f.E.Balance("BANK",bank:f.Bank));Eq(M(200000),f.E.Balance("BANK",bank:f.Bank2));Eq(M(1000000),f.E.Balance("BANK"));Eq(0L,f.E.Balance("EXPENSE"));Fail(()=>f.E.Transfer(Day(),f.Bank,f.Bank,M(100),""));});
        Test("Staff advance, site expense and refund reconcile",()=>{var f=new Fixture();f.Advance(staff:true);f.E.SiteExpense(Day(),f.Emp,f.Site,f.Cat,M(6000),null,"Bill");Eq(M(990000),f.E.Balance("BANK"));Eq(M(4000),f.E.Balance("STAFF",employee:f.Emp,site:f.Site));f.E.Move(new("Staff Advance Refund",Day(),M(4000),f.Bank,Employee:f.Emp,Site:f.Site),true);Eq(0L,f.E.Balance("STAFF"));Eq(M(994000),f.E.Balance("BANK"));Eq(M(6000),f.E.Balance("EXPENSE"));});
        Test("Staff overspend and wrong site rejected",()=>{var f=new Fixture();f.Advance(1000,true);Fail(()=>f.E.SiteExpense(Day(),f.Emp,f.Site,f.Cat,M(1001),null,""));Eq(0L,f.E.Balance("EXPENSE"));});
        Test("Direct site expense only reduces bank once",()=>{var f=new Fixture();f.E.SiteExpense(Day(),f.Emp,f.Site,f.Cat,M(500),f.Bank,"Fuel");Eq(M(999500),f.E.Balance("BANK"));Eq(0L,f.E.Balance("STAFF"));});
        Test("Employee advance remains separate from staff and loan",()=>{var f=new Fixture();f.Advance();f.E.Move(new("Employee Advance Refund",Day(),M(2000),f.Bank,Employee:f.Emp),true);Eq(M(8000),f.E.Balance("ADV"));Eq(0L,f.E.Balance("STAFF"));Eq(0L,f.E.Balance("ELOAN"));});
        Test("Payroll acceptance calculation, paid Sundays, EPF and ESIC eligibility",()=>{var f=new Fixture();var r=f.E.Calculate(2026,10,[new(f.Emp,2)])[0];Eq(31,r.CalendarDays);Eq(4,r.Sundays);Eq(29m,r.PayableDays);Eq(M(28064.52m),r.Earned);Eq(M(14032.26m),r.Basic);Eq(M(1684),r.EPF);Eq(0L,r.ESIC);Eq(M(26380.52m),r.Net);});
        Test("Joining and leaving days bound eligible salary",()=>{var f=new Fixture();f.E.SaveMaster("Employee",new(){["Name"]="Employee 1",["JoinDay"]=Day(2026,10,10),["LeaveDay"]=Day(2026,10,20)},f.Emp);var r=f.E.Calculate(2026,10,[new(f.Emp,1)])[0];Eq(11,r.EligibleDays);Eq(10m,r.PayableDays);Eq(M(9677.42m),r.Earned);Fail(()=>f.E.Calculate(2026,10,[new(f.Emp,12)]));});
        Test("Leap-year and non-leap calendar",()=>{var f=new Fixture();f.E.SaveMaster("Employee",new(){["Name"]="Employee 1",["JoinDay"]=Day(2020,1,1)},f.Emp);Eq(29,f.E.Calculate(2024,2,[new(f.Emp)])[0].CalendarDays);Eq(28,f.E.Calculate(2025,2,[new(f.Emp)])[0].CalendarDays);});
        Test("EPF ceiling and configurable contribution basis",()=>{var f=new Fixture(50000);Eq(M(1800),f.E.Calculate(2026,10,[new(f.Emp)])[0].EPF);f.E.SaveStatutory(new(Day(),EPFCeiling:M(25000),EPFBasis:"Gross"));Eq(M(3000),f.E.Calculate(2026,10,[new(f.Emp)])[0].EPF);});
        Test("ESIC eligibility is not a contribution cap",()=>{var f=new Fixture(20000);var r=f.E.Calculate(2026,10,[new(f.Emp,Bonus:M(10000))])[0];Eq(M(225),r.ESIC);Eq(M(30000),r.ESICWage);});
        Test("ESIC continuation and applicability switches",()=>{var f=new Fixture();Eq(M(225),f.E.Calculate(2026,10,[new(f.Emp,ESICContinuation:true)])[0].ESIC);f.E.SaveMaster("Employee",new(){["Name"]="Employee 1",["EPF"]=0,["ESIC"]=0},f.Emp);var r=f.E.Calculate(2026,10,[new(f.Emp,ESICContinuation:true)])[0];Eq(0L,r.EPF);Eq(0L,r.ESIC);});
        Test("Payroll advance plus separate loan recovery; bank unchanged",()=>{var f=new Fixture();f.Advance();long loan=f.Loan();long bank=f.E.Balance("BANK");long payroll=f.E.FinalizePayroll(2026,10,[new(f.Emp,2,M(1000),new(){[loan]=M(2000)})]);Eq(bank,f.E.Balance("BANK"));Eq(M(9000),f.E.Balance("ADV"));Eq(M(8000),f.E.Balance("ELOAN"));Eq(-M(23380.52m),f.E.Balance("SALARY"));Fail(()=>f.E.FinalizePayroll(2026,10,[new(f.Emp)]));});
        Test("Advance over-recovery and negative net payroll reject",()=>{var f=new Fixture();Fail(()=>f.E.FinalizePayroll(2026,10,[new(f.Emp,Advance:M(1))]));Fail(()=>f.E.FinalizePayroll(2026,10,[new(f.Emp,OtherDeduction:M(40000))]));Eq(0L,f.E.Balance("WAGES"));});
        Test("Payroll partial salary payment, payment status and reopen protection",()=>{var f=new Fixture();long p=f.E.FinalizePayroll(2026,10,[new(f.Emp)]);using var d=f.E.Open();long row=d.N("SELECT Id FROM PayrollRow WHERE PayrollId=@p0",p);long voucher=f.E.Move(new("Salary/Wages",Day(2026,11,1),M(10000),f.Bank,Employee:f.Emp,PayrollRow:row),false);Eq(-M(18200),f.E.Balance("SALARY"));Eq(M(990000),f.E.Balance("BANK"));Eq(M(30000),f.E.Balance("WAGES"));Fail(()=>f.E.ReopenPayroll(p,"Correction"));f.E.Reverse(voucher,Day(2026,11,1),"Reverse salary");f.E.ReopenPayroll(p,"Attendance correction");Eq(0L,f.E.Balance("SALARY"));Eq(0L,f.E.Balance("WAGES"));f.E.FinalizePayroll(2026,10,[new(f.Emp,1)]);});
        Test("Payroll reopening restores advance and employee loan balances",()=>{var f=new Fixture();f.Advance();long loan=f.Loan();long p=f.E.FinalizePayroll(2026,10,[new(f.Emp,Advance:M(1000),Loans:new(){[loan]=M(2000)})]);f.E.ReopenPayroll(p,"Correction");Eq(M(10000),f.E.Balance("ADV"));Eq(M(10000),f.E.Balance("ELOAN"));});
        Test("Direct employee loan repayment and excess rejection",()=>{var f=new Fixture();long loan=f.Loan();f.E.Move(new("Employee Loan Repayment",Day(),M(2000),f.Bank,Employee:f.Emp,Instrument:loan),true);Eq(M(8000),f.E.Balance("ELOAN"));Fail(()=>f.E.Move(new("Employee Loan Repayment",Day(),M(9000),f.Bank,Employee:f.Emp,Instrument:loan),true));});
        Test("FD creation and closure separate principal and interest",()=>{var f=new Fixture();long fd=f.FD();Eq(M(10000),f.E.Balance("FD"));f.E.CloseFD(fd,Day(2027,10,1),f.Bank,M(700));Eq(0L,f.E.Balance("FD"));Eq(-M(700),f.E.Balance("INTERESTIN"));Eq(M(1000700),f.E.Balance("BANK"));Fail(()=>f.E.CloseFD(fd,Day(2027,10,1),f.Bank,0));});
        Test("FD renewal is atomic",()=>{var f=new Fixture();long fd=f.FD();long replacement=f.E.RenewFD(fd,Day(2027,10,1),f.Bank,M(700),new("FD","FD-2",Day(2027,10,1),M(10700),f.Bank,MaturityDay:Day(2028,10,1)));Eq(M(10700),f.E.Balance("FD"));Eq(M(990000),f.E.Balance("BANK"));});
        Test("Failed renewal rolls back closure and interest",()=>{var f=new Fixture();long fd=f.FD();Fail(()=>f.E.RenewFD(fd,Day(2027,10,1),f.Bank,M(700),new("FD","FD-1",Day(2027,10,1),M(10700),f.Bank,MaturityDay:Day(2028,10,1))));Eq(M(10000),f.E.Balance("FD"));Eq(0L,f.E.Balance("INTERESTIN"));});
        Test("Multiple FDs link to one BG; BG closure retains FDs and lien alert",()=>{var f=new Fixture();long fd1=f.FD(),fd2=f.FD("FD-2"),bg=f.BG();f.E.LinkFD(bg,fd1,Day());f.E.LinkFD(bg,fd2,Day());f.E.CloseBG(bg,Day(2027,2,2),"Returned");Eq(M(20000),f.E.Balance("FD"));Fail(()=>f.E.CloseFD(fd1,Day(2027,3,1),f.Bank,0));var report=f.E.Report("BG Register",Day(),Day(2027,3,1));Eq("BG CLOSED — FD/LIEN RELEASE PENDING",Value.Text(report.Rows[0]["Status"]));f.E.ReleaseFD(fd1,Day(2027,3,1),"Release letter");f.E.CloseFD(fd1,Day(2027,3,1),f.Bank,0);Eq(M(10000),f.E.Balance("FD"));});
        Test("BG charges post only expense and bank",()=>{var f=new Fixture();long bg=f.BG();f.E.Move(new("BG Charges",Day(),M(1000),f.Bank,BG:bg),false);Eq(M(1000),f.E.Balance("CHARGES"));Eq(M(999000),f.E.Balance("BANK"));});
