        Test("Historical employee loan opening and recovery",()=>{var f=new Fixture();long loan=f.E.CreateInstrument(new("Employee Loan","OLD-EL",Day(),M(5000),Employee:f.Emp,RecoveryDay:Day(),OpeningBalance:true));Eq(M(1000000),f.E.Balance("BANK"));f.E.Move(new("Employee Loan Repayment",Day(),M(1000),f.Bank,Employee:f.Emp,Instrument:loan),true);Eq(M(4000),f.E.Balance("ELOAN"));});
        Test("Opening customer receivable settlement",()=>{var f=new Fixture();f.E.Opening(Day(),[new("AR",M(1000),Party:f.Customer)],"Opening receivable");f.E.Move(new("Customer Receipt",Day(),M(500),f.Bank,Party:f.Customer,SettleOpeningBalance:true),true);Eq(M(500),f.E.Balance("AR"));});
        Test("Opening settlement cannot consume invoice debt",()=>{var f=new Fixture();f.Invoice();Fail(()=>f.E.Move(new("Customer Receipt",Day(),M(500),f.Bank,Party:f.Customer,SettleOpeningBalance:true),true));});
        Test("Opening supplier settlement",()=>{var f=new Fixture();f.E.Opening(Day(),[new("AP",-M(1000),Party:f.Supplier)],"Opening payable");f.E.Move(new("Supplier Payment",Day(),M(500),f.Bank,Party:f.Supplier,SettleOpeningBalance:true),false);Eq(-M(500),f.E.Balance("AP"));});
        Test("Customer advance adjusts invoice without second bank receipt",()=>{var f=new Fixture();long inv=f.Invoice();f.E.Move(new("Customer Advance",Day(),M(1000),f.Bank,Party:f.Customer),true);long bank=f.E.Balance("BANK");f.E.ApplyCustomerAdvance(Day(),f.Customer,[new(inv,M(1000))],"Advance applied");Eq(bank,f.E.Balance("BANK"));Eq(M(180),f.E.Outstanding(inv));Eq(0L,f.E.Balance("CUSTADV"));});
        Test("Customer advance refund reduces liability",()=>{var f=new Fixture();f.E.Move(new("Customer Advance",Day(),M(1000),f.Bank,Party:f.Customer),true);f.E.Move(new("Customer Refund",Day(),M(400),f.Bank,Party:f.Customer,CounterAccount:"CUSTADV"),false);Eq(-M(600),f.E.Balance("CUSTADV"));});
        Test("Backdated recovery cannot overdraw a later advance balance",()=>{var f=new Fixture();f.Advance(1000);f.E.Move(new("Employee Advance Refund",Day(2026,10,10),M(800),f.Bank,Employee:f.Emp),true);Fail(()=>f.E.Move(new("Employee Advance Refund",Day(2026,10,5),M(800),f.Bank,Employee:f.Emp),true));Eq(M(200),f.E.Balance("ADV"));});
        Test("Other lien blocks FD closure until released",()=>{var f=new Fixture();long fd=f.E.CreateInstrument(new("FD","LIEN-FD",Day(),M(10000),f.Bank,Type:"Other Lien",MaturityDay:Day(2027,10,1)));Fail(()=>f.E.CloseFD(fd,Day(2027,10,1),f.Bank,0));f.E.ReleaseFD(fd,Day(2027,10,1),"Release letter");f.E.CloseFD(fd,Day(2027,10,1),f.Bank,0);Eq(0L,f.E.Balance("FD"));});
        Test("Business loan EMI projection separates principal and interest",()=>{var f=new Fixture();long loan=f.E.CreateInstrument(new("Business Loan","EMI-1",Day(),M(100000),Rate:12,EMI:M(10000),RecoveryDay:Day(2026,11,1)));f.E.Move(new("Business Loan Received",Day(),M(100000),f.Bank,Instrument:loan),true);var schedule=f.E.Report("EMI Schedule",Day(2026,11,1),Day(2027,12,1));Eq(M(1000),Value.Long(schedule.Rows[0]["Interest (INR)"]));Eq(M(9000),Value.Long(schedule.Rows[0]["Principal (INR)"]));Eq(0L,Value.Long(schedule.Rows[schedule.Rows.Count-1]["Closing (INR)"]));});
        Test("Audit and postings cannot be edited through SQL",()=>{var f=new Fixture();using var d=f.E.Open();bool rejected=false;try{d.Exec("UPDATE Posting SET Amount=1");}catch{rejected=true;}Eq(true,rejected);rejected=false;try{d.Exec("DELETE FROM Audit");}catch{rejected=true;}Eq(true,rejected);});

        Test("Historical invoice outstanding follows receipt and reversal dates",()=>{var f=new Fixture();long inv=f.Invoice();long receipt=f.Receipt(inv,500);f.E.Reverse(receipt,Day(2026,11,1),"Receipt reversal");var before=f.E.Report("Customer Outstanding",Day(),Day(2026,10,2));Eq(M(1180),Value.Long(before.Rows[0]["Outstanding (INR)"]));var mid=f.E.Report("Customer Outstanding",Day(),Day(2026,10,31));Eq(M(680),Value.Long(mid.Rows[0]["Outstanding (INR)"]));var after=f.E.Report("Customer Outstanding",Day(),Day(2026,11,2));Eq(M(1180),Value.Long(after.Rows[0]["Outstanding (INR)"]));});
        Test("Invoice cancellation and GST reversal stay in their effective periods",()=>{var f=new Fixture();long inv=f.Invoice();f.E.CancelInvoice(inv,Day(2026,11,1),"Cancelled later");var october=f.E.Report("Customer Outstanding",Day(),Day(2026,10,31));Eq(M(1180),Value.Long(october.Rows[0]["Outstanding (INR)"]));Eq(0,f.E.Report("Customer Outstanding",Day(),Day(2026,11,2)).Rows.Count);Eq(M(90),Value.Long(f.E.Report("Sales GST Summary",Day(),Day(2026,10,31)).Rows[0]["CGST (INR)"]));Eq(-M(90),Value.Long(f.E.Report("Sales GST Summary",Day(2026,11,1),Day(2026,11,30)).Rows[0]["CGST (INR)"]));});
        foreach(string directory in Created){try{Directory.Delete(directory,true);}catch(IOException){}}
        Console.WriteLine($"RESULT | {passed} passed | {failed} failed");Environment.ExitCode=failed==0?0:1;
    }
